def reconcile_storm(t, old_window, new_window, stacked_windows):
    """reload/rollback 改变 window 时搬运两层记录；仅改 limits 不动。"""
    keep = max([new_window] + stacked_windows)
    views = (rate_view, move_view)
    archives = (rate_archive, move_archive)
    if new_window < old_window:
